-- Recall foundations (backlog #43, phase 1).
--
-- 1. appointments.is_booked — separates a DUE visit (generated by the care
--    arc / a recall rule: the clinic wants the patient back around this date)
--    from a BOOKED one (the patient has agreed to the date). Only booked rows
--    get the day-before "your appointment is tomorrow" push; before this,
--    every arc-generated date fired that push even though nobody had booked
--    it. Clean slate (Kurt, 2026-11-03): no backfill — existing rows are
--    demo data and start unbooked.
-- 2. patients.do_not_contact / contact_preference — outreach guardrails the
--    call list (and later automated reminders) must respect.
-- 3. patient_contacts — append-only outreach attempt history. The
--    follow_up_* columns on patients stay as the "latest attempt" cache that
--    drives queue cooldowns; this table is the full record (attempt counts,
--    escalation after N unanswered tries).
-- 4. last_visit_date backfill from completed appointments (completing a
--    visit never advanced it before; the app now does).

alter table public.appointments
  add column if not exists is_booked boolean not null default false;

alter table public.patients
  add column if not exists do_not_contact boolean not null default false,
  add column if not exists contact_preference text
    check (contact_preference in ('phone', 'text', 'email'));

create table public.patient_contacts (
  id         uuid primary key default gen_random_uuid(),
  patient_id uuid not null references public.patients(id) on delete cascade,
  clinic_id  uuid not null references public.clinics(id),
  staff_id   uuid references public.staff(id) on delete set null,
  channel    text not null default 'call'
             check (channel in ('call', 'text', 'email', 'in_person', 'letter')),
  reason     text,
  outcome    text not null
             check (outcome in ('reached', 'voicemail', 'no_answer', 'scheduled', 'declined')),
  note       text,
  created_at timestamptz not null default now()
);

create index patient_contacts_patient_created_idx
  on public.patient_contacts (patient_id, created_at desc);

alter table public.patient_contacts enable row level security;

create policy "authenticated_read_all_patient_contacts"
  on public.patient_contacts for select to authenticated
  using (true);

create policy "Staff insert clinic contacts"
  on public.patient_contacts for insert to authenticated
  with check (clinic_id = my_clinic_id() and staff_id = auth.uid());

create policy "Staff delete clinic contacts"
  on public.patient_contacts for delete to authenticated
  using (clinic_id = my_clinic_id());

update public.patients p
set last_visit_date = c.last_done
from (
  select patient_id, max(appointment_date) as last_done
  from public.appointments
  where status = 'completed' and appointment_date <= now()
  group by patient_id
) c
where c.patient_id = p.id
  and (p.last_visit_date is null or p.last_visit_date < c.last_done);

-- Day-before push now fires for booked visits only. Body otherwise identical
-- to the live definition (migration 011).
create or replace function public.get_due_notifications()
returns table (patient_id uuid, kind text, ref_key text, detail text)
language sql
stable
set search_path = ''
as $$
  -- 1. Appointment — the day before a BOOKED appointment.
  select a.patient_id,
         'appointment_24h'::text,
         a.id::text,
         a.appointment_type
  from public.appointments a
  where a.status = 'scheduled'
    and a.is_booked
    and (a.appointment_date at time zone 'America/Denver')::date
        = (now() at time zone 'America/Denver')::date + 1
    and exists (
      select 1 from public.push_subscriptions ps
      where ps.patient_id = a.patient_id and ps.active
    )
    and not exists (
      select 1 from public.notification_log nl
      where nl.patient_id = a.patient_id
        and nl.kind = 'appointment_24h'
        and nl.ref_key = a.id::text
    )

  union all

  -- 2. Cleaning — a monthly nudge for anyone with an active fitting.
  select distinct
         df.patient_id,
         'cleaning_monthly'::text,
         to_char((now() at time zone 'America/Denver')::date, 'YYYY-MM'),
         null::text
  from public.device_fittings df
  where df.active
    and exists (
      select 1 from public.push_subscriptions ps
      where ps.patient_id = df.patient_id and ps.active
    )
    and not exists (
      select 1 from public.notification_log nl
      where nl.patient_id = df.patient_id
        and nl.kind = 'cleaning_monthly'
        and nl.ref_key = to_char((now() at time zone 'America/Denver')::date, 'YYYY-MM')
    )

  union all

  -- 3. Warranty — 90d / 30d / expired. Windowed so a missed cron day catches up.
  select w.patient_id, w.kind, w.ref_key, w.detail
  from (
    select df.patient_id,
           case
             when df.warranty_expiry <= (now() at time zone 'America/Denver')::date
               then 'warranty_expired'
             when df.warranty_expiry <= (now() at time zone 'America/Denver')::date + 30
               then 'warranty_30d'
             else 'warranty_90d'
           end as kind,
           df.id::text as ref_key,
           null::text as detail
    from public.device_fittings df
    where df.active
      and df.warranty_expiry is not null
      and df.warranty_expiry <= (now() at time zone 'America/Denver')::date + 90
      and exists (
        select 1 from public.push_subscriptions ps
        where ps.patient_id = df.patient_id and ps.active
      )
  ) w
  where not exists (
    select 1 from public.notification_log nl
    where nl.patient_id = w.patient_id
      and nl.kind = w.kind
      and nl.ref_key = w.ref_key
  )

  union all

  -- 4. Upgrade — once, ~4 years after the care plan started.
  select p.id,
         'upgrade_year4'::text,
         p.id::text,
         null::text
  from public.patients p
  where p.care_plan_start_date is not null
    and p.care_plan_start_date
        <= (now() at time zone 'America/Denver')::date - interval '4 years'
    and p.upgrade_outcome is null
    and exists (
      select 1 from public.device_fittings df
      where df.patient_id = p.id and df.active
    )
    and exists (
      select 1 from public.push_subscriptions ps
      where ps.patient_id = p.id and ps.active
    )
    and not exists (
      select 1 from public.notification_log nl
      where nl.patient_id = p.id
        and nl.kind = 'upgrade_year4'
        and nl.ref_key = p.id::text
    );
$$;
